// Pool di aplikasi Node.js (library pg)
import { Pool } from 'pg';

const pool = new Pool({
  host: '127.0.0.1',
  port: 6432,          // lewat PgBouncer, bukan langsung ke PostgreSQL
  database: 'myapp',
  user: 'app',
  password: process.env.DB_PASSWORD,
  max: 10,             // koneksi per instance aplikasi
  idleTimeoutMillis: 30000,  // tutup koneksi menganggur setelah 30 detik
  connectionTimeoutMillis: 2000, // gagal cepat kalau pool penuh
});

const result = await pool.query('SELECT * FROM products WHERE id = $1', [42]);
